import numpy as np
def equation(t, x, v, params):
    p = params
    return (p[0] + p[1]*t + p[2]*x + p[3]*x**3 + p[4]*np.cos(x) + p[5]*np.sin(x)
            + p[6]*v + p[7]*np.sin(v) + p[8]/v + p[9]*t*v*v)
